int handle_untagged_response(struct ImapData *idata) {
    if (!idata) {
        return -1;
    }

    const char *response = idata->current_response;

    if (strncmp(response, "* EXISTS", 8) == 0) {
        int count;
        sscanf(response + 2, "%d", &count);
        idata->new_mail_count = count;
        idata->mail_count_updated = 1;
    } else if (strncmp(response, "* EXPUNGE", 9) == 0) {
        int sequence;
        sscanf(response + 2, "%d", &sequence);
        idata->mailbox->flags &= ~IMAP_MAILBOX_FLAG_OPEN;
        idata->mailbox->flags |= IMAP_MAILBOX_FLAG_EXPUNGED;
    } else if (strncmp(response, "* FETCH", 7) == 0) {
        // Assume parsing is handled by some helper function
        int success = parse_fetch_response(idata);
        if (!success) {
            return -1;
        }
    } else if (strncmp(response, "* CAPABILITY", 12) == 0) {
        // Update capability flags
        update_capabilities(idata, response + 2);
    } else if (strncmp(response, "* OK", 4) == 0) {
        // Log OK response for debugging
        log_debug("IMAP OK response received: %s", response);
    } else if (strncmp(response, "* NO", 4) == 0) {
        log_error("IMAP NO response: %s", response + 5);
        return -1;
    } else if (strncmp(response, "* BAD", 5) == 0) {
        log_error("IMAP BAD response: %s", response + 6);
        return -1;
    } else if (strncmp(response, "* BYE", 5) == 0) {
        log_debug("Server is closing connection.");
        return 0; // Indicate connection closing
    }

    // Check for fatal errors
    if (idata->error_state != IMAP_ERROR_NONE) {
        log_error("Error state detected in ImapData: %d", idata->error_state);
        return -1;
    }

    return 0;
}

